    properties: { source: { type: 'string', enum: ['site', 'articles', 'guides', 'faq'] }, search: { type: 'string' }, intent: { type: 'string', enum: ['general', 'learning', 'installation'] }, categoryId: { type: 'integer', minimum: 1 }, page: { type: 'integer', minimum: 1 } } },
