  const prices = text => [...replyText(text).replace(/\*/g, '').matchAll(/(\d[\d,٬،.]*)\s*(هزار|میلیون)?\s*(تومان|تومن|ریال|دلار|usd|irr|irt)(?=$|[\s،.,؛!؟|)])/g)];
