        .replace(/\[[^\]\n]*\]\(/g, '').replace(/[\s)*#>،:.-]/g, ''));
      if (adjacent || /هر دو|هر یک|هر کدام|همه(?:ٔ| ی)? دوره|همه(?:ٔ| ی)? محصول/.test(block)) return 'unverified_price';
