    .replace(/https?:\/\/\S+|\S+@\S+|(?:sk|pk|api|token|bearer)_[a-z0-9_-]{8,}|[a-z0-9_-]{24,}|\+?[0-9][0-9 ()-]{6,}[0-9]/g, '[redacted]')
