    || /(?:صفحه|برگه).*(?:خدمات|پیدا|معرفی|نشانی)|(?:جستجو|جست وجو|سرچ).*سایت/.test(q)) return 'site';
  if (/پرفروش|جدیدترین|تازه ترین/.test(q)) return 'products';
